    public void sendBulkRequest(SnmpSession session, Oid startOid, int nonRepeaters, int maxRepetitions) {
        // Prepare the PDU for the bulk request
        Pdu bulkPdu = new Pdu();
        bulkPdu.setType(Pdu.BULK_REQUEST);
        bulkPdu.add(new VariableBinding(startOid));

        // Set nonRepeaters and maxRepetitions
        bulkPdu.setNonRepeaters(nonRepeaters);
        bulkPdu.setMaxRepetitions(maxRepetitions);

        // Send the bulk request and handle the response
        try {
            ResponseEvent responseEvent = session.send(bulkPdu);
            if (responseEvent.getError() != null) {
                throw new SnmpException("Error in response: " + responseEvent.getError());
            }

            Pdu responsePdu = responseEvent.getResponse();
            if (responsePdu != null) {
                processResponse(responsePdu);
            }

        } catch (IOException e) {
            throw new SnmpException("IO Exception while sending SNMP bulk request", e);
        }
    }

