  @Autowired
  private NonReportingFacilityReportMapper reportMapper;

  @Override
  public MasterReport generateReport(NonReportingFacilityParam params) {
    List<ResultRow> resultRows = reportMapper.getNonReportingFacilities(params);
    int totalFacilities = reportMapper.getTotalFacilities(params);
    int totalNonReporting = resultRows.size();

    double percentageNonReporting = totalFacilities > 0 ? (double) totalNonReporting / totalFacilities * 100 : 0;

    Map<String, Object> reportData = new HashMap<>();
    reportData.put(TOTAL_FACILITIES, totalFacilities);
    reportData.put(TOTAL_NON_REPORTING, totalNonReporting);
    reportData.put(PERCENTAGE_NON_REPORTING, percentageNonReporting);
    reportData.put(REPORT_FILTER_PARAM_VALUES, ParameterAdaptor.adapt(params));

    return new MasterReport(resultRows, reportData);
  }

