        String input = "<p>This is a <a href=\"http://example.com\">link</a> and <script>alert('xss');</script></p>";

        String safeHtml = HtmlSanitizer.sanitize(input, new HtmlPolicyBuilder()
            .allowElements("p", "a")
            .allowAttributes("href").onElements("a")
            .toFactory());

        System.out.println(safeHtml);
