        String input = "<p>This is a <a href='http://example.com'>link</a> to an example.</p>";

        String sanitized = HtmlSanitizer.sanitize(input, new HtmlPolicyBuilder()
            .allowElements("p", "a")
            .allowAttributes("href").onElements("a")
            .toFactory()
        );

        System.out.println(sanitized);
    }
}

