public void testRTreeConstruction() throws IOException {
    RInlineTree tree = new RInlineTree(input);
    List<RLayer> layers = new ArrayList<>();
    Iterator<RLayer> iterator = tree.iterator();

    while (iterator.hasNext()) {
        layers.add(iterator.next());
    }

    Assert.assertEquals("Number of layers should match", ans.getRowCount(), layers.size());

    for (int i = 0; i < layers.size(); i++) {
