import org.jclouds.http.HttpResponse;
import org.jclouds.http.functions.ParseJson;
import org.jclouds.profitbricks.domain.IpBlock;
import org.jclouds.profitbricks.domain.IpBlockList;
import org.jclouds.json.Json;
import com.google.common.base.Function;
import com.google.common.collect.Lists;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;

@Singleton
public class IpBlockListResponseHandler extends ParseJson<IpBlockList> {

    @Inject
    public IpBlockListResponseHandler(Json json) {
        super(json, IpBlockList.class);
    }

    @Override
    public IpBlockList apply(HttpResponse response) {
        List<IpBlock> ipBlocks = Lists.newArrayList();
        // Parse the response to extract IP blocks
        // Assuming the JSON structure contains an array of IP blocks
        for (Object ipBlockJson : json.fromJson(response.getPayload(), List.class)) {
            IpBlock ipBlock = json.fromJson(ipBlockJson, IpBlock.class);
            ipBlocks.add(ipBlock);
        }
        return new IpBlockList(ipBlocks);
    }
}

