import org.jclouds.http.HttpResponse;
import org.jclouds.json.Json;
import org.jclouds.json.JsonBinder;
import org.jclouds.profitbricks.domain.IpBlock;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;

@Singleton
public class IpBlockListResponseHandler {

    private final JsonBinder jsonBinder;

    @Inject
    public IpBlockListResponseHandler(JsonBinder jsonBinder) {
        this.jsonBinder = jsonBinder;
    }

    public List<IpBlock> handle(HttpResponse response) {
        if (response.getStatusCode() == 200) {
            return jsonBinder.bindToList(IpBlock.class, response.getPayload().openStream());
        } else {
            throw new RuntimeException("Failed to retrieve IP blocks: " + response.getStatusCode());
        }
    }
}

