    }
    synchronized (this) {
        // Add the envelope to the outgoing messages queue
        outgoingMessages.add(envelope);
        // Notify the receiving thread that a new message is available
        notifyAll();
    }
}

public Envelope receive() {
    synchronized (this) {
        while (incomingMessages.isEmpty()) {
            try {
                // Wait until a message is available
                wait();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Thread interrupted while waiting to receive a message", e);
            }
        }
        // Get the next message from the incoming messages queue
        return incomingMessages.remove(0);
    }
}

