                }

                System.out.println(priv.getUser(authenticationToken));
            } catch (Exception e) {
                System.err.println("got Exception: "+e);
            }
            Thread.sleep(1000);

            long end = System.currentTimeMillis();
            System.out.println("took " + (end - start) + " milisec");
        }
    }

