    private static final int TIMEOUT = 5000; // Timeout in milliseconds

    private final String wassUrl;

    public WassSessionIdRetriever(String wassUrl) {
        this.wassUrl = wassUrl;
    }

    @Override
    public String retrieveSessionId(String username, String password) throws IOException {
        CloseableHttpClient httpClient = HttpClientBuilder.create()
                .setDefaultRequestConfig(RequestConfig.custom()
                        .setSocketTimeout(TIMEOUT)
                        .setConnectTimeout(TIMEOUT)
                        .build())
                .build();

        try {
            URI uri = new URIBuilder(wassUrl)
                    .setParameter("username", username)
