public void someFunction() {
    ArrayList<Tower> towers = new ArrayList<>();
    towers.add(new GotoTower(new Vector(1, 1), Color.RED));
    towers.add(new TryCatchTower(new Vector(2, 2), Color.BLUE));

    for (Tower tower : towers) {
        Renderer.render(tower);
    }

    GameObjectHandler gameObjectHandler = new GameObjectHandler();
    for (Tower tower : towers) {
        gameObjectHandler.addGameObject(tower);
    }

    EnemyController enemyController = new EnemyController();
    ArrayList<Enemy> enemies = enemyController.spawnEnemies(5);

    for (Enemy enemy : enemies) {
        gameObjectHandler.addGameObject(enemy);
    }

    Path path = new Path();
    path.addNode(new Node(new Vector(0, 0), NodeType.START));
    path.addNode(new Node(new Vector(3, 3), NodeType.END));

    gameObjectHandler.setPath(path);
}

