java
public void someFunction() {
    ArrayList<Enemy> enemies = EnemyController.getEnemies();
    for (Enemy enemy : enemies) {
        if (enemy.isActive() && enemy.getHealth() > 0) {
            Vector position = enemy.getPosition();
            Renderer.drawEnemy(position, enemy.getTypeColor());
            if (enemy.isAtNode()) {
                Node currentNode = enemy.getCurrentNode();
                Path pathToNextNode = currentNode.getPathToNextNode();
                if (pathToNextNode != null) {
                    Vector nextPosition = pathToNextNode.getNextPosition();
                    enemy.moveTowards(nextPosition);
                }
            }
        }
    }
}

