/**
 * <p>
 * このクラスは、システムが回復不可能な例外を表現するクラスです。
 * 回復不可能であるとは、システムの運用管理者などのシステム外部からの介入がなければ、
 * 正常稼働を継続することができない状態を指します。
 * システムが回復できない場合にこの例外クラスを利用してください。
 * </p>
 * @see AbstractException
 */
public class SystemException extends AbstractException {

    private static final long serialVersionUID = 2463775997084510094L;

    /**
     * エラーコードのみを指定するコンストラクタです。
     * @param code エラーコード
     */
    public SystemException(String code) {
        super(code);
    }

    /**
     * エラーコードとメッセージの置換文字列を指定するコンストラクタです。
     * @param code エラーコード
     * @param args 置換文字列
     */
    public SystemException(String code, Map<String, ?> args) {
        super(code, args);
    }

    /**
     * エラーコードと原因となった例外の置換文字列を指定するコンストラクタです。
     * @param code エラーコード
     * @param cause 原因となった例外
     */
    public SystemException(String code, Throwable cause) {
        super(code, cause);
    }

    /**
     * エラーコードとメッセージ、原因となった例外の置換文字列を指定するコンストラクタです。
     * @param code エラーコード
     * @param args 置換文字列
     * @param cause 原因となった例外
     */
    public SystemException(String code, Throwable cause, Map<String, String> args) {
        super(code, args, cause);
    }
}

