public class LegacyShiroFilter extends IniShiroFilter {

    @Override
    protected WebSecurityManager createWebSecurityManager() {
        ApplicationContext applicationContext = (ApplicationContext) getServletContext().getAttribute(ApplicationAttributes.APPLICATION_CONTEXT);
        return (WebSecurityManager) applicationContext.getBean("shiroSecurityManager");
    }

    @Override
    protected void initFilter() throws Exception {
        super.initFilter();
        Map<String, String> initParams = getInitParams();
        if (CollectionUtils.isEmpty(initParams)) {
            throw new IllegalArgumentException("No Shiro configuration found in init parameters.");
        }
        Ini ini = new Ini();
        ini.load(initParams.get("shiroConfig"));
        getSecurityManager().setConfig(ini);
    }
}

