public class UriResolverImpl {

    public URI resolveUri(String uriString) throws URISyntaxException {
        if (uriString == null || uriString.isEmpty()) {
            throw new IllegalArgumentException("URI string cannot be null or empty");
        }

        URI uri = new URI(uriString);

        if (!isValidUri(uri)) {
            throw new URISyntaxException(uriString, "Invalid URI");
        }

        return uri;
    }

    private boolean isValidUri(URI uri) {
        // Implement validation logic for the URI
        return uri.getScheme() != null && uri.getHost() != null;
    }
}

