    public AffineMotionField(PointND center, SimpleVector axis, double angle, SimpleVector translation) {
        this.center = center;
        this.axis = axis;
        this.angle = angle;
        this.translation = translation;
        this.toCenter = new Translation(center.scale(-1));
        this.back = new Translation(center);
        this.rotationMat = Rotations.createRotationMatrix(axis, angle);
    }

    @Override
    public Transform getTransform(double time) {
        Transform rotation = new ScaleRotate(rotationMat);
        Transform translationTransform = new Translation(translation);
        return new ComboTransform(toCenter, rotation, translationTransform, back);
    }

    @Override
    public PointND getMotion(double time, PointND point) {
        Transform transform = getTransform(time);
        return transform.apply(point);
    }

    @Override
    public SimpleVector getVelocity(double time, PointND point) {
        // Calculate the velocity based on the motion field
        SimpleVector velocity = new SimpleVector(translation);
        SimpleMatrix angularVelocity = rotationMat.times(new SimpleMatrix(axis).scale(angle));
        return velocity.add(angularVelocity);
    }

