    public AffineMotionField(SimpleVector axis, double angle, SimpleVector translation, PointND center) {
        this.axis = axis;
        this.angle = angle;
        this.translation = translation;
        this.center = center;
        this.toCenter = new Translation(center.multiply(-1));
        this.rotationMat = Rotations.getRotationMatrix(axis, angle);
        this.back = new Translation(center);
    }

    @Override
    public PointND apply(PointND point, double time) {
        PointND transformedPoint = point.clone();
        transformedPoint = toCenter.apply(transformedPoint);
        transformedPoint = rotationMat.multiply(transformedPoint);
        transformedPoint = back.apply(transformedPoint);
        transformedPoint = transformedPoint.add(translation);
        return transformedPoint;
    }

    @Override
    public Transform getTransform() {
        ComboTransform combo = new ComboTransform();
        combo.addTransform(toCenter);
        combo.addTransform(new ScaleRotate(rotationMat));
        combo.addTransform(back);
        combo.addTransform(new Translation(translation));
        return combo;
    }
